/**
 * @typedef {object} AttributeNode
 * @property {string} name attribute name (raw case preserved)
 * @property {string} value attribute value (empty string when valueless)
 */

/**
 * @typedef {object} TextNode
 * @property {"text"} type node type
 * @property {string} data text content (character references decoded)
 */

/**
 * @typedef {object} CommentNode
 * @property {"comment"} type node type
 * @property {string} data comment content (without the `<!-- -->` delimiters)
