/** @typedef {ElementNode | TextNode | CommentNode | DoctypeNode} ChildNode */

/**
 * @typedef {object} DocumentNode
 * @property {"document"} type node type
 * @property {ChildNode[]} children child nodes
 */

const NS_HTML = 0;
const NS_MATHML = 1;
const NS_SVG = 2;

// HTML void elements: always self-closing, never hold children.
const VOID_ELEMENTS = new Set([
	"area",
	"base",
	"br",
	"col",
	"embed",
	"hr",
	"img",
	"input",
	"link",
	"meta",
	"param",
	"source",
	"track",
	"wbr"
